document.addEventListener('click',function(e){var t=e.target.closest&&e.target.closest('.js-wpml-ls-item-toggle');document.querySelectorAll('.js-wpml-ls-sub-menu').forEach(function(m){var mine=t&&t.parentNode.contains(m);m.style.visibility=mine&&m.style.visibility!=='visible'?'visible':'hidden'});if(t)e.preventDefault()});